import { EventEmitter, once, on, addAbortListener } from 'node:events';

export async function report() {
  const line = (name, value) => console.log(name, JSON.stringify(value));
  const shape = e => [e.name, e.code, e.message];
  const reject = async (name, fn) => {
    try { await fn(); line(name, 'no error'); } catch (e) { line(name, shape(e)); }
  };
  const counts = em => em.eventNames().map(n => [String(n), em.listenerCount(n)]);
  for (const value of [null, false, 3, 'bad', [], () => {}]) {
    await reject('once options', () => once(new EventEmitter(), 'x', value));
    await reject('on options', () => on(new EventEmitter(), 'x', value));
  }
  for (const value of [null, false, {}, 3]) {
    await reject('once signal', () => once(new EventEmitter(), 'x', { signal: value }));
    await reject('on signal', () => on(new EventEmitter(), 'x', { signal: value }));
    await reject('abort signal', () => addAbortListener(value, () => {}));
  }
  await reject('abort undefined', () => addAbortListener(undefined, () => {}));
  await reject('abort listener', () => addAbortListener(new AbortController().signal, null));
  await reject('once emitter', () => once({}, 'x'));
  await reject('on emitter', () => on({}, 'x'));
  for (const name of ['highWaterMark', 'lowWaterMark', 'highWatermark', 'lowWatermark']) {
    for (const value of ['2', 0, -1, 1.5, NaN, Infinity, Number.MAX_SAFE_INTEGER + 1]) {
      await reject(name, () => on(new EventEmitter(), 'x', { [name]: value }));
    }
  }
  {
    const em = new EventEmitter(), ac = new AbortController(), event = Symbol('ready');
    const promise = once(em, event, { signal: ac.signal });
    line('once registered', counts(em));
    em.emit(event, 'ready', 42);
    line('once result', await promise);
    line('once cleaned', counts(em));
    ac.abort('after completion');
  }
  {
    const em = new EventEmitter(), ac = new AbortController(), failure = new Error('failure');
    const promise = once(em, 'ready', { signal: ac.signal });
    em.emit('error', failure);
    try { await promise; } catch (e) { line('once error identity', e === failure); }
    line('once error cleaned', counts(em));
    const errorEvent = once(em, 'error'); em.emit('error', failure);
    line('once error event', (await errorEvent)[0] === failure);
  }
  for (const preaborted of [false, true]) {
    const em = new EventEmitter(), ac = new AbortController(), cause = { why: 'cancelled' };
    ac.signal.addEventListener('abort', e => e.stopImmediatePropagation());
    if (preaborted) ac.abort(cause);
    const promise = once(em, 'ready', { signal: ac.signal });
    if (!preaborted) ac.abort(cause);
    try { await promise; } catch (e) { line('once aborted', [preaborted, ...shape(e), e.cause === cause]); }
    line('once abort cleaned', counts(em));
  }
  {
    const target = new EventTarget(), ac = new AbortController();
    target.addEventListener('ready', e => e.stopImmediatePropagation());
    const promise = once(target, 'ready', { signal: ac.signal });
    target.dispatchEvent(new Event('error'));
    const event = new Event('ready'); target.dispatchEvent(event);
    line('once target', (await promise)[0] === event);
    ac.abort();
    const aborted = once(target, 'never', { signal: ac.signal });
    await reject('once target aborted', () => aborted);
    const active = new AbortController(), waiting = once(target, 'never', { signal: active.signal });
    active.abort('target cancellation'); await reject('once target active abort', () => waiting);
    const controller = new AbortController(), signalEvent = once(controller.signal, 'abort');
    controller.abort(); line('once signal event', (await signalEvent)[0] instanceof Event);
  }
  {
    const em = new EventEmitter(), symbol = Symbol('item');
    const iterator = on(em, symbol, { close: ['end', 'close'] });
    line('iterator self', iterator[Symbol.asyncIterator]() === iterator);
    em.emit(symbol, 1, 'a'); em.emit(symbol, 2); em.emit('end');
    line('iterator closed listeners', counts(em));
    const values = []; for await (const value of iterator) values.push(value);
    line('buffered close', values);
    line('closed next', await iterator.next());
  }
  {
    const em = new EventEmitter(), iterator = on(em, 'item');
    const first = iterator.next(), second = iterator.next(), third = iterator.next();
    em.emit('item', 'first'); em.emit('item', 'second');
    line('pending delivery', [await first, await second]);
    line('return result', await iterator.return('ignored'));
    line('pending return', await third);
    line('return cleaned', counts(em));
  }
  {
    const em = new EventEmitter(), iterator = on(em, 'item'), failure = new Error('failure');
    em.emit('item', 'buffered'); em.emit('error', failure);
    line('error drains buffer', await iterator.next());
    try { await iterator.next(); } catch (e) { line('iterator error identity', e === failure); }
    line('error next done', await iterator.next());
    line('error cleaned', counts(em));
    const errorIterator = on(em, 'error'); em.emit('error', failure);
    line('iterator error event', (await errorIterator.next()).value[0] === failure);
    await errorIterator.return();
  }
  {
    const em = new EventEmitter(), iterator = on(em, 'x'), failure = new Error('pending failure');
    const first = iterator.next().catch(e => e === failure), second = iterator.next();
    em.emit('error', failure);
    line('pending error', [await first, await second]);
  }
  for (const preaborted of [false, true]) {
    const em = new EventEmitter(), ac = new AbortController(), cause = { why: 'cancelled' };
    ac.signal.addEventListener('abort', e => e.stopImmediatePropagation());
    if (preaborted) ac.abort(cause);
    try {
      const iterator = on(em, 'x', { signal: ac.signal });
      const first = iterator.next().catch(e => [shape(e), e.cause === cause]), second = iterator.next();
      ac.abort(cause);
      line('iterator aborted', [await first, await second, await iterator.next()]);
    } catch (e) { line('iterator preaborted', [shape(e), e.cause === cause]); }
    line('iterator abort cleaned', counts(em));
  }
  {
    const em = new EventEmitter(), ac = new AbortController(), iterator = on(em, 'x', { signal: ac.signal });
    em.emit('x', 'buffered'); ac.abort('buffered abort');
    line('abort drains buffer', await iterator.next());
    await reject('buffered abort', () => iterator.next());
    line('buffered abort done', await iterator.next());
  }
  {
    const em = new EventEmitter(), iterator = on(em, 'x', { close: ['end'] });
    const a = iterator.next(), b = iterator.next(); em.emit('end');
    line('pending close', [await a, await b, await iterator.next()]);
  }
  {
    const em = new EventEmitter(), iterator = on(em, 'x');
    const failure = new Error('thrown');
    line('iterator throw return', iterator.throw(failure) === undefined);
    try { await iterator.next(); } catch (e) { line('iterator throw identity', e === failure); }
    line('iterator throw cleaned', counts(em));
    for (const value of [undefined, null, 'failure', {}]) await reject('iterator throw type', () => iterator.throw(value));
  }
  for (const legacy of [false, true]) {
    const em = new EventEmitter(), log = [];
    em.pause = () => { log.push('pause'); }; em.resume = () => { log.push('resume'); };
    const options = legacy ? { highWatermark: 2, lowWatermark: 2 } : { highWaterMark: 2, lowWaterMark: 2, highWatermark: 9 };
    const iterator = on(em, 'item', options);
    em.emit('item', 1); em.emit('item', 2); line('watermark threshold', log.slice());
    em.emit('item', 3); line('watermark pause', log.slice());
    await iterator.next(); line('watermark still paused', log.slice());
    await iterator.next(); line('watermark resume', log.slice());
    await iterator.return();
  }
  {
    const em = new EventEmitter(), iterator = on(em, 'x');
    for (let i = 0; i < 3000; i++) em.emit('x', i);
    let sum = 0; for (let i = 0; i < 3000; i++) sum += (await iterator.next()).value[0];
    line('queue compaction', sum); await iterator.return();
  }
  {
    const em = new EventEmitter(), iterator = on(em, 'x');
    queueMicrotask(() => { em.emit('x', 'loop'); });
    for await (const value of iterator) { line('loop break', value); break; }
    line('loop break cleaned', counts(em));
    const ac = new AbortController(), returned = on(em, 'x', { signal: ac.signal });
    await returned.return(); ac.abort(); line('return removes abort', await returned.next());
  }
  {
    const target = new EventTarget(), iterator = on(target, 'item', { close: ['end'] });
    target.dispatchEvent(new Event('error'));
    const event = new Event('item'); target.dispatchEvent(event); target.dispatchEvent(new Event('end'));
    line('iterator target', [(await iterator.next()).value[0] === event, await iterator.next()]);
  }
  {
    const ac = new AbortController(), log = [];
    ac.signal.addEventListener('abort', e => { log.push('stop'); e.stopImmediatePropagation(); });
    ac.signal.addEventListener('abort', () => { log.push('ordinary'); });
    const disposable = addAbortListener(ac.signal, function(e) { log.push([this === ac.signal, e instanceof Event, e.type]); });
    line('disposable shape', [Object.getPrototypeOf(disposable) === null, typeof disposable[Symbol.dispose]]);
    ac.abort(); ac.abort(); disposable[Symbol.dispose](); disposable[Symbol.dispose](); line('resistant abort', log);
  }
  {
    const ac = new AbortController(), log = [];
    const first = addAbortListener(ac.signal, () => { log.push('first'); second[Symbol.dispose](); });
    const second = addAbortListener(ac.signal, () => { log.push('second'); });
    const disposed = addAbortListener(ac.signal, () => { log.push('disposed'); });
    disposed[Symbol.dispose](); ac.abort(); first[Symbol.dispose](); line('disposed abort', log);
  }
  {
    const signal = AbortSignal.abort('already aborted'), log = [];
    const disposable = addAbortListener(signal, function(e) { log.push([e === undefined, this === undefined]); });
    disposable[Symbol.dispose](); line('preaborted scheduling', log.slice());
    await Promise.resolve(); line('preaborted callback', log);
  }
  {
    const ac = new AbortController(); let calls = 0;
    const listener = () => { calls++; };
    const a = addAbortListener(ac.signal, listener), b = addAbortListener(ac.signal, listener);
    ac.abort(); line('duplicate abort listener', calls); a[Symbol.dispose](); b[Symbol.dispose]();
    const other = new AbortController(), c = addAbortListener(other.signal, listener), d = addAbortListener(other.signal, listener);
    c[Symbol.dispose](); other.abort(); line('duplicate disposal', calls); d[Symbol.dispose]();
  }
  {
    const em = new EventEmitter(), ac = new AbortController(); let signals = 0, closes = 0, removed = 0;
    const original = ac.signal.removeEventListener.bind(ac.signal);
    ac.signal.removeEventListener = (...args) => { removed++; return original(...args); };
    const options = { get signal() { signals++; return ac.signal; }, get close() { closes++; return ['end']; } };
    const promise = once(em, 'x', options); em.emit('x', 1); await promise;
    const iterator = on(em, 'x', options); await iterator.return();
    line('option getters and abort cleanup', [signals, closes, removed]);
    let lows = 0;
    await reject('watermark validation order', () => on(em, 'x', { highWaterMark: 0, get lowWaterMark() { lows++; return 1; } }));
    line('invalid high skips low', lows);
  }
}
